1568	absl::Status DirectSession::GetOrCreateExecutors(
1569	    absl::Span<const std::string> inputs, absl::Span<const std::string> outputs,
1570	    absl::Span<const std::string> target_nodes,
1571	    ExecutorsAndKeys** executors_and_keys, RunStateArgs* run_state_args) {
1572	  int64_t handle_name_counter_value = -1;
1573	  if (LogMemory::IsEnabled() || run_state_args->is_partial_run) {
1574	    handle_name_counter_value = handle_name_counter_.fetch_add(1);
1575	  }
1576	
1577	  std::string debug_tensor_watches_summary;
1578	  if (!run_state_args->debug_options.debug_tensor_watch_opts().empty()) {
1579	    debug_tensor_watches_summary = SummarizeDebugTensorWatches(
1580	        run_state_args->debug_options.debug_tensor_watch_opts());
1581	  }
1582	
1583	  // Fast lookup path, no sorting.
1584	  const std::string key = strings::StrCat(
1585	      absl::StrJoin(inputs, ","), "->", absl::StrJoin(outputs, ","), "/",
1586	      absl::StrJoin(target_nodes, ","), "/", run_state_args->is_partial_run,
1587	      "/", debug_tensor_watches_summary);
1588	  // Set the handle, if it's needed to log memory or for partial run.
1589	  if (handle_name_counter_value >= 0) {
1590	    run_state_args->handle = absl::StrCat(key, ";", handle_name_counter_value);
1591	  }
1592	
1593	  // See if we already have the executors for this run.
1594	  {
1595	    mutex_lock l(executor_lock_);  // could use reader lock
1596	    auto it = executors_.find(key);
1597	    if (it != executors_.end()) {
1598	      *executors_and_keys = it->second.get();
1599	      return absl::OkStatus();
1600	    }
1601	  }
1602	
